package com.stacklab.controller;
import com.stacklab.repository.*;import io.swagger.v3.oas.annotations.security.SecurityRequirement;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.time.Instant;import java.util.*;
@RestController @RequestMapping("/api/analytics") @PreAuthorize("hasAnyRole('ADMIN','MANAGER')") @SecurityRequirement(name="bearerAuth")public class AnalyticsController{private final TaskRepository tasks;private final ProjectRepository projects;public AnalyticsController(TaskRepository t,ProjectRepository p){tasks=t;projects=p;}
 @GetMapping public Map<String,Object> overview(){long done=tasks.countByStatus(com.stacklab.entity.TaskStatus.COMPLETED);long total=tasks.count();Map<String,Object> out=new LinkedHashMap<>();out.put("totalProjects",projects.count());out.put("totalTasks",total);out.put("completedTasks",done);out.put("pendingTasks",total-done);out.put("overdueTasks",tasks.countOverdue(Instant.now()));return out;}
 @GetMapping("/breakdown")public Map<String,Object> breakdown(){Map<String,Object> m=new LinkedHashMap<>();m.put("byEmployee",tasks.countsByEmployee().stream().map(r->Map.of("employeeId",r[0],"employeeName",r[1],"taskCount",r[2])).toList());m.put("byStatus",tasks.countsByStatus().stream().map(r->Map.of("status",r[0],"count",r[1])).toList());m.put("byPriority",tasks.countsByPriority().stream().map(r->Map.of("priority",r[0],"count",r[1])).toList());return m;}
 @GetMapping("/employees/{id}/performance")public Map<String,Object> performance(@PathVariable Long id){long assigned=tasks.assignedCount(id),completed=tasks.completedCount(id),onTime=tasks.onTimeCount(id),late=tasks.lateCount(id);Map<String,Object> m=new LinkedHashMap<>();m.put("employeeId",id);m.put("assigned",assigned);m.put("completed",completed);m.put("completionRatePercent",assigned==0?0.0:completed*100.0/assigned);m.put("onTimeCompletions",onTime);m.put("overdueCompletions",late);m.put("averageCompletionSeconds",tasks.avgCompletionSeconds(id));return m;}}
